"use client";

import { clamp01, mixOklch, useFramecnTheme } from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";

export type SliderThumbState = "idle" | "hover" | "press";

export interface SliderStyle {
  value: number;
  thumbScale: number;
  ringOpacity: number;
}

export interface SliderProps {
  value?: number;
  thumbState?: SliderThumbState;
  style?: SliderStyle;
  width?: number;
  showValue?: boolean;
  theme?: Partial<FramecnTheme>;
  className?: string;
}

const TRACK_HEIGHT = 6;
const THUMB_HEIGHT = 16;
const THUMB_WIDTH = 16;
const THUMB_RADIUS = THUMB_HEIGHT / 2;
const RING_WIDTH = 4;

const clampValue = (value: number): number => clamp01(value / 100) * 100;

export const sliderThumbStyle = (
  thumbState: SliderThumbState
): {
  thumbScale: number;
  ringOpacity: number;
} => {
  switch (thumbState) {
    case "hover": {
      return { ringOpacity: 1, thumbScale: 1.1 };
    }
    case "press": {
      return { ringOpacity: 1, thumbScale: 1.15 };
    }
    default: {
      return { ringOpacity: 0, thumbScale: 1 };
    }
  }
};

export interface SliderStyleContext {
  track: string;
  range: string;
  thumbBg: string;
  thumbRing: string;
  ring: string;
  valueText: string;
}

export const sliderStyleContext = (
  theme: FramecnTheme
): SliderStyleContext => ({
  range: theme.primary,
  ring: mixOklch(theme.ring, "transparent", 0.5),
  thumbBg: theme.background,
  thumbRing: theme.primary,
  track: theme.muted,
  valueText: theme.foreground,
});

export const Slider = ({
  value = 0,
  thumbState = "idle",
  style,
  width = 320,
  showValue = false,
  theme: themeOverride,
  className,
}: SliderProps) => {
  const theme = useFramecnTheme(themeOverride);
  const ctx = sliderStyleContext(theme);
  const thumb = sliderThumbStyle(thumbState);
  const v: SliderStyle = style ?? {
    ringOpacity: thumb.ringOpacity,
    thumbScale: thumb.thumbScale,
    value,
  };
  const pct = clampValue(v.value);
  return (
    <div
      className={className}
      style={{
        alignItems: "center",
        display: "inline-flex",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        height: THUMB_HEIGHT,
        position: "relative",
        width,
      }}
    >
      <div
        style={{
          background: ctx.track,
          borderRadius: TRACK_HEIGHT / 2,
          height: TRACK_HEIGHT,
          position: "relative",
          width: "100%",
        }}
      >
        <div
          style={{
            background: ctx.range,
            borderRadius: TRACK_HEIGHT / 2,
            bottom: 0,
            left: 0,
            position: "absolute",
            top: 0,
            width: `${pct}%`,
          }}
        />
      </div>

      <div
        style={{
          left: `${pct}%`,
          position: "absolute",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${v.thumbScale})`,
        }}
      >
        <div
          style={{
            background: ctx.ring,
            borderRadius: THUMB_RADIUS + RING_WIDTH,
            height: THUMB_HEIGHT + RING_WIDTH * 2,
            left: "50%",
            opacity: v.ringOpacity,
            position: "absolute",
            top: "50%",
            transform: "translate(-50%, -50%)",
            width: THUMB_WIDTH + RING_WIDTH * 2,
          }}
        />

        <div
          style={{
            background: ctx.thumbBg,
            border: `1px solid ${ctx.thumbRing}`,
            borderRadius: THUMB_RADIUS,
            boxShadow: "0 1px 3px rgb(0 0 0 / 10%), 0 1px 2px rgb(0 0 0 / 10%)",
            boxSizing: "border-box",
            height: THUMB_HEIGHT,
            position: "relative",
            width: THUMB_WIDTH,
          }}
        />
        {showValue && (
          <span
            style={{
              bottom: "100%",
              color: ctx.valueText,
              fontSize: 12,
              fontVariantNumeric: "tabular-nums",
              fontWeight: 500,
              left: "50%",
              marginBottom: 8,
              position: "absolute",
              transform: "translateX(-50%)",
            }}
          >
            {Math.round(pct)}
          </span>
        )}
      </div>
    </div>
  );
};

"use client";

import { clamp01, easings, useCurrentFrame } from "@/lib/framecn-ui";
import type { EasingName } from "@/lib/framecn-ui";
import { sliderThumbStyle } from "@/components/framecn/slider";
import type {
  SliderStyle,
  SliderThumbState,
} from "@/components/framecn/slider";

export interface SliderStep {
  at: number;
  value?: number;
  thumbState?: SliderThumbState;
  duration?: number;
  easing?: EasingName;
}

export const DEFAULT_DURATION = 18;

export interface SliderTransitionOptions {
  speed?: number;
  defaultDuration?: number;
}

export const tweenSliderStyle = (
  a: SliderStyle,
  b: SliderStyle,
  t: number
): SliderStyle => ({
  ringOpacity: a.ringOpacity + (b.ringOpacity - a.ringOpacity) * t,
  thumbScale: a.thumbScale + (b.thumbScale - a.thumbScale) * t,
  value: a.value + (b.value - a.value) * t,
});

const valueAt = (
  steps: SliderStep[],
  raw: number,
  defaultDuration: number
): number => {
  const valueSteps = steps.filter(
    (s): s is SliderStep & { value: number } => s.value !== undefined
  );
  if (valueSteps.length === 0) {
    return 0;
  }
  const [first] = valueSteps;
  if (raw <= first.at) {
    return first.value;
  }
  let toIndex = valueSteps.length - 1;
  for (let i = 1; i < valueSteps.length; i += 1) {
    if (valueSteps[i].at > raw) {
      toIndex = i;
      break;
    }
  }
  const last = valueSteps.at(-1);
  if (!last) {
    return first.value;
  }
  const pastLast = raw >= last.at;
  const to = pastLast ? last : valueSteps[toIndex];
  const from = pastLast ? last : valueSteps[toIndex - 1];
  if (to === undefined || from === undefined) {
    return first.value;
  }
  const dur = to.duration ?? defaultDuration;
  const ease = easings[to.easing ?? "out"];
  const start = to.at - dur;
  const t = pastLast || dur <= 0 ? 1 : ease(clamp01((raw - start) / dur));
  return from.value + (to.value - from.value) * t;
};

const thumbAt = (
  steps: SliderStep[],
  raw: number,
  defaultDuration: number
): {
  thumbScale: number;
  ringOpacity: number;
} => {
  const thumbSteps = steps.filter(
    (s): s is SliderStep & { thumbState: SliderThumbState } =>
      s.thumbState !== undefined
  );
  if (thumbSteps.length === 0) {
    return sliderThumbStyle("idle");
  }
  const [first] = thumbSteps;
  if (raw <= first.at) {
    return sliderThumbStyle(first.thumbState);
  }
  let toIndex = thumbSteps.length - 1;
  for (let i = 1; i < thumbSteps.length; i += 1) {
    if (thumbSteps[i].at > raw) {
      toIndex = i;
      break;
    }
  }
  const last = thumbSteps.at(-1);
  if (!last) {
    return sliderThumbStyle(first.thumbState);
  }
  const pastLast = raw >= last.at;
  const to = pastLast ? last : thumbSteps[toIndex];
  const from = pastLast ? last : thumbSteps[toIndex - 1];
  if (to === undefined || from === undefined) {
    return sliderThumbStyle(first.thumbState);
  }
  const dur = to.duration ?? defaultDuration;
  const ease = easings[to.easing ?? "out"];
  const start = to.at - dur;
  const t = pastLast || dur <= 0 ? 1 : ease(clamp01((raw - start) / dur));
  const a = sliderThumbStyle(from.thumbState);
  const b = sliderThumbStyle(to.thumbState);
  return {
    ringOpacity: a.ringOpacity + (b.ringOpacity - a.ringOpacity) * t,
    thumbScale: a.thumbScale + (b.thumbScale - a.thumbScale) * t,
  };
};

export const sliderStyleAt = (
  steps: SliderStep[],
  raw: number,
  opts: SliderTransitionOptions = {}
): SliderStyle => {
  const { defaultDuration = DEFAULT_DURATION } = opts;
  const value = valueAt(steps, raw, defaultDuration);
  const thumb = thumbAt(steps, raw, defaultDuration);
  return {
    ringOpacity: thumb.ringOpacity,
    thumbScale: thumb.thumbScale,
    value,
  };
};

export const useSliderTransition = (
  steps: SliderStep[],
  opts: SliderTransitionOptions = {}
): SliderStyle => {
  const { speed = 1 } = opts;
  const raw = useCurrentFrame() * speed;
  return sliderStyleAt(steps, raw, opts);
};
